CREATE TABLE public.biz_positions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE,name text NOT NULL,description text NOT NULL DEFAULT '',level integer NOT NULL DEFAULT 0 CHECK(level>=0),unit_kind text NOT NULL CHECK(unit_kind IN ('system','department','team','individual')),sort_order integer NOT NULL DEFAULT 0,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.biz_positions TO authenticated; GRANT ALL ON public.biz_positions TO service_role;
ALTER TABLE public.biz_positions ENABLE ROW LEVEL SECURITY;
CREATE POLICY biz_positions_read ON public.biz_positions FOR SELECT TO authenticated USING(public.biz_org_can_manage() OR public.biz_workflow_manage());
CREATE TABLE public.biz_appointments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),position_id uuid NOT NULL REFERENCES public.biz_positions(id),user_id uuid NOT NULL REFERENCES public.profiles(id),system_id uuid REFERENCES public.biz_systems(id),department_id uuid REFERENCES public.biz_departments(id),team_id uuid REFERENCES public.biz_teams(id),scope_kind text NOT NULL CHECK(scope_kind IN ('system','department','team','individual')),started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','ended','cancelled')),position_snapshot jsonb NOT NULL,actor_id uuid NOT NULL REFERENCES public.profiles(id),replaces_id uuid REFERENCES public.biz_appointments(id),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.biz_appointments TO authenticated; GRANT ALL ON public.biz_appointments TO service_role;
ALTER TABLE public.biz_appointments ENABLE ROW LEVEL SECURITY;
CREATE POLICY biz_appointments_read ON public.biz_appointments FOR SELECT TO authenticated USING(public.biz_org_can_manage() OR public.biz_workflow_manage() OR user_id=auth.uid());
CREATE INDEX biz_appointment_scope ON public.biz_appointments(position_id,system_id,department_id,team_id,started_at,ended_at);
CREATE INDEX biz_appointment_user ON public.biz_appointments(user_id,started_at,ended_at);
CREATE FUNCTION public.biz_position_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$BEGIN
IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Không xóa chức vụ; hãy ngừng áp dụng.'; END IF;
IF TG_OP='UPDATE' AND (NEW.unit_kind<>OLD.unit_kind OR NEW.code IS DISTINCT FROM OLD.code) AND (EXISTS(SELECT 1 FROM public.biz_appointments WHERE position_id=OLD.id) OR EXISTS(SELECT 1 FROM public.biz_approval_workflows w,jsonb_array_elements(w.steps||w.director_steps) s WHERE s->>'position_id'=OLD.id::text) OR (OLD.code IS NOT NULL AND EXISTS(SELECT 1 FROM public.biz_management_assignments WHERE position=OLD.code))) THEN RAISE EXCEPTION 'Chức vụ đã có bổ nhiệm hoặc quy trình; không đổi loại đơn vị/mã.'; END IF;
IF btrim(NEW.name)='' THEN RAISE EXCEPTION 'Cần tên chức vụ.'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER biz_position_guard BEFORE INSERT OR UPDATE OR DELETE ON public.biz_positions FOR EACH ROW EXECUTE FUNCTION public.biz_position_guard();
CREATE FUNCTION public.biz_appointment_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE p public.biz_positions;unit uuid;BEGIN
PERFORM pg_advisory_xact_lock(hashtext('biz_org_structure'));
IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Không xóa lịch sử bổ nhiệm.'; END IF;
IF TG_OP='UPDATE' AND (NEW.position_id<>OLD.position_id OR NEW.user_id<>OLD.user_id OR NEW.system_id IS DISTINCT FROM OLD.system_id OR NEW.department_id IS DISTINCT FROM OLD.department_id OR NEW.team_id IS DISTINCT FROM OLD.team_id OR NEW.started_at<>OLD.started_at OR NEW.scope_kind<>OLD.scope_kind OR NEW.position_snapshot<>OLD.position_snapshot OR NEW.actor_id<>OLD.actor_id OR NEW.replaces_id IS DISTINCT FROM OLD.replaces_id) THEN RAISE EXCEPTION 'Bổ nhiệm bất biến; kết thúc rồi tạo quyết định mới.'; END IF;
IF TG_OP='UPDATE' AND OLD.status<>'active' THEN RAISE EXCEPTION 'Quyết định đã kết thúc hoặc hủy.'; END IF;
IF NEW.ended_at IS NOT NULL AND NEW.ended_at<=NEW.started_at THEN RAISE EXCEPTION 'Ngày kết thúc phải sau ngày bắt đầu.'; END IF;
SELECT * INTO p FROM public.biz_positions WHERE id=NEW.position_id;
IF TG_OP='INSERT' THEN
IF NOT p.active OR NEW.scope_kind<>p.unit_kind THEN RAISE EXCEPTION 'Chức vụ đã ngừng hoặc phạm vi không phù hợp.'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.user_id AND status='Đang hoạt động') THEN RAISE EXCEPTION 'Nhân viên chưa hoạt động.'; END IF;
IF NEW.scope_kind='system' THEN
IF NEW.system_id IS NULL OR NEW.department_id IS NOT NULL OR NEW.team_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public.biz_systems WHERE id=NEW.system_id AND active) THEN RAISE EXCEPTION 'Phạm vi Hệ không hợp lệ.'; END IF;
ELSIF NEW.scope_kind='department' THEN
IF NEW.department_id IS NULL OR NEW.team_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public.biz_departments d JOIN public.biz_systems s ON s.id=d.system_id WHERE d.id=NEW.department_id AND s.id=NEW.system_id AND d.active AND s.active) THEN RAISE EXCEPTION 'Phạm vi Phòng không hợp lệ.'; END IF;
ELSIF NEW.scope_kind='team' THEN
IF NOT EXISTS(SELECT 1 FROM public.biz_teams t JOIN public.biz_departments d ON d.id=t.department_id JOIN public.biz_systems s ON s.id=d.system_id WHERE t.id=NEW.team_id AND d.id=NEW.department_id AND s.id=NEW.system_id AND t.active AND d.active AND s.active) THEN RAISE EXCEPTION 'Phạm vi Nhóm không hợp lệ.'; END IF;
ELSE
IF NOT EXISTS(SELECT 1 FROM public.biz_departments d JOIN public.biz_systems s ON s.id=d.system_id WHERE d.id=NEW.department_id AND s.id=NEW.system_id AND d.active AND s.active) OR (NEW.team_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.biz_teams WHERE id=NEW.team_id AND department_id=NEW.department_id AND active)) THEN RAISE EXCEPTION 'Đơn vị nhân viên không hợp lệ.'; END IF;
END IF;NEW.position_snapshot:=to_jsonb(p);END IF;
unit:=CASE NEW.scope_kind WHEN 'system' THEN NEW.system_id WHEN 'team' THEN NEW.team_id ELSE NEW.department_id END;
IF NEW.status<>'cancelled' AND EXISTS(SELECT 1 FROM public.biz_appointments a WHERE a.id<>NEW.id AND a.status<>'cancelled' AND tstzrange(a.started_at,a.ended_at,'[)') && tstzrange(NEW.started_at,NEW.ended_at,'[)') AND a.position_id=NEW.position_id AND a.scope_kind=NEW.scope_kind AND CASE a.scope_kind WHEN 'system' THEN a.system_id WHEN 'team' THEN a.team_id ELSE a.department_id END=unit AND (NEW.scope_kind<>'individual' OR a.user_id=NEW.user_id)) THEN RAISE EXCEPTION 'Bổ nhiệm có phạm vi hoặc thời gian hiệu lực mâu thuẫn.'; END IF;
IF NEW.status<>'cancelled' AND p.code IN ('director','department_head','team_lead') AND EXISTS(SELECT 1 FROM public.biz_management_assignments a WHERE a.position=p.code AND CASE p.code WHEN 'director' THEN a.system_id WHEN 'department_head' THEN a.department_id ELSE a.team_id END=unit AND tstzrange(a.started_at,a.ended_at,'[)') && tstzrange(NEW.started_at,NEW.ended_at,'[)')) THEN RAISE EXCEPTION 'Trùng thời gian với bổ nhiệm quản lý hiện có.'; END IF; RETURN NEW;END $$;
CREATE TRIGGER biz_appointment_guard BEFORE INSERT OR UPDATE OR DELETE ON public.biz_appointments FOR EACH ROW EXECUTE FUNCTION public.biz_appointment_guard();
CREATE FUNCTION public.biz_position_save(_data jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE id_ uuid:=nullif(_data->>'id','')::uuid;old_ jsonb;BEGIN
IF NOT public.biz_org_can_manage() THEN RAISE EXCEPTION 'Không có quyền quản lý chức vụ.';END IF;PERFORM pg_advisory_xact_lock(hashtext('biz_org_structure'));
IF id_ IS NULL THEN INSERT INTO public.biz_positions(name,description,level,unit_kind,sort_order,active) VALUES(btrim(_data->>'name'),coalesce(_data->>'description',''),coalesce((_data->>'level')::int,0),_data->>'unit_kind',coalesce((_data->>'sort_order')::int,0),coalesce((_data->>'active')::boolean,true)) RETURNING id INTO id_;
ELSE SELECT to_jsonb(p) INTO old_ FROM public.biz_positions p WHERE id=id_ FOR UPDATE;IF old_ IS NULL THEN RAISE EXCEPTION 'Không tìm thấy chức vụ.';END IF;UPDATE public.biz_positions SET name=btrim(_data->>'name'),description=coalesce(_data->>'description',''),level=coalesce((_data->>'level')::int,0),unit_kind=_data->>'unit_kind',sort_order=coalesce((_data->>'sort_order')::int,0),active=coalesce((_data->>'active')::boolean,true) WHERE id=id_;END IF;
INSERT INTO public.biz_org_events(actor_id,action,payload) VALUES(auth.uid(),'position',jsonb_build_object('id',id_,'old',old_,'new',_data));RETURN id_;END $$;
CREATE FUNCTION public.biz_appointment_save(_data jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE id_ uuid;previous_ public.biz_appointments;start_ timestamptz:=coalesce(nullif(_data->>'started_at','')::timestamptz,clock_timestamp());finish_ timestamptz:=nullif(_data->>'ended_at','')::timestamptz;replace_ uuid:=nullif(_data->>'replaces_id','')::uuid;BEGIN
IF NOT public.biz_org_can_manage() THEN RAISE EXCEPTION 'Không có quyền bổ nhiệm.';END IF;PERFORM pg_advisory_xact_lock(hashtext('biz_org_structure'));
IF _data->>'action' IN ('end','cancel') THEN SELECT * INTO previous_ FROM public.biz_appointments WHERE id=(_data->>'id')::uuid FOR UPDATE;IF previous_.id IS NULL THEN RAISE EXCEPTION 'Không tìm thấy bổ nhiệm.';END IF;
IF _data->>'action'='cancel' THEN IF previous_.started_at<=clock_timestamp() THEN RAISE EXCEPTION 'Chỉ hủy quyết định chưa hiệu lực.';END IF;UPDATE public.biz_appointments SET status='cancelled' WHERE id=previous_.id;
ELSE IF finish_ IS NULL OR finish_<=previous_.started_at OR finish_>clock_timestamp() THEN RAISE EXCEPTION 'Mốc kết thúc không hợp lệ.';END IF;UPDATE public.biz_appointments SET ended_at=finish_,status='ended' WHERE id=previous_.id;END IF;id_:=previous_.id;
ELSE IF replace_ IS NOT NULL THEN SELECT * INTO previous_ FROM public.biz_appointments WHERE id=replace_ FOR UPDATE;IF previous_.id IS NULL OR previous_.user_id<>(_data->>'user_id')::uuid OR start_<=previous_.started_at THEN RAISE EXCEPTION 'Quyết định thay thế không hợp lệ.';END IF;UPDATE public.biz_appointments SET ended_at=start_ WHERE id=replace_;END IF;
INSERT INTO public.biz_appointments(position_id,user_id,system_id,department_id,team_id,scope_kind,started_at,ended_at,position_snapshot,actor_id,replaces_id) VALUES((_data->>'position_id')::uuid,(_data->>'user_id')::uuid,nullif(_data->>'system_id','')::uuid,nullif(_data->>'department_id','')::uuid,nullif(_data->>'team_id','')::uuid,_data->>'scope_kind',start_,finish_,'{}',auth.uid(),replace_) RETURNING id INTO id_;END IF;
INSERT INTO public.biz_org_events(actor_id,action,payload) VALUES(auth.uid(),'appointment',jsonb_build_object('id',id_,'old',to_jsonb(previous_),'new',_data));RETURN id_;END $$;
CREATE FUNCTION public.biz_positions_read() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$BEGIN IF NOT public.biz_org_can_manage() AND NOT public.biz_workflow_manage() THEN RAISE EXCEPTION 'Không có quyền xem chức vụ.';END IF;RETURN jsonb_build_object('positions',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY sort_order,level DESC,name),'[]') FROM public.biz_positions p),'appointments',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY started_at DESC),'[]') FROM public.biz_appointments a),'server_now',now());END $$;
REVOKE ALL ON FUNCTION public.biz_position_guard(),public.biz_appointment_guard(),public.biz_position_save(jsonb),public.biz_appointment_save(jsonb),public.biz_positions_read() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.biz_position_save(jsonb),public.biz_appointment_save(jsonb),public.biz_positions_read() TO authenticated;
COMMENT ON TABLE public.biz_appointments IS 'Effective-dated dynamic position decisions; legacy management assignments remain intact and are resolved alongside these decisions.';